  4	final class IntBinaryHeap {
  5	    private static final int DEFAULT_CAPACITY = 10;
  6	
  7	    private int[] elements;
  8	    private int size;
  9	
 10	    IntBinaryHeap() {
 11	        this(DEFAULT_CAPACITY);
 12	    }
 13	
 14	    IntBinaryHeap(int initialCapacity) {
 15	        if (initialCapacity < 0) {
 16	            throw new IllegalArgumentException("initial capacity must be non-negative");
 17	        }
 18	
 19	        elements = new int[initialCapacity];
 20	        size = 0;
 21	    }
 22	
 23	    IntBinaryHeap(int[] values) {
 24	        if (values == null) {
 25	            throw new IllegalArgumentException("values must not be null");
 26	        }
 27	
 28	        elements = copyOf(values);
 29	        size = values.length;
 30	        rebuildHeap();
 31	    }
 32	
 33	    boolean offer(int value) {
 34	        ensureCapacity(size + 1);
 35	        elements[size] = value;
 36	        siftUp(size);
 37	        size++;
 38	        return true;
 39	    }
 40	
 41	    void addAll(int... values) {
 42	        if (values == null) {
 43	            throw new IllegalArgumentException("values must not be null");
 44	        }
 45	
 46	        if (values.length == 0) {
 47	            return;
 48	        }
 49	
 50	        appendAll(values);
 51	        rebuildHeap();
 52	    }
 53	
 54	    int peek() {
 55	        ensureNotEmpty();
 56	        return elements[0];
 57	    }
 58	
 59	    int removeMin() {
 60	        ensureNotEmpty();
 61	        return removeAt(0);
 62	    }
 63	
 64	    int extractMin() {
 65	        if (isEmpty()) {
 66	            return Integer.MAX_VALUE;
 67	        }
 68	
 69	        return removeMin();
 70	    }
 71	
 72	    int removeAt(int index) {
 73	        validateOccupiedIndex(index);
 74	
 75	        int removedValue = elements[index];
 76	        int lastIndex = size - 1;
 77	        int lastValue = elements[lastIndex];
 78	        elements[lastIndex] = 0;
 79	        size--;
 80	        if (index == lastIndex) {
 81	            return removedValue;
 82	        }
 83	
 84	        elements[index] = lastValue;
 85	        restoreHeapAt(index);
 86	        return removedValue;
 87	    }
 88	
 89	    void updateValue(int index, int newValue) {
 90	        validateOccupiedIndex(index);
 91	
 92	        int currentValue = elements[index];
 93	        elements[index] = newValue;
 94	        if (newValue < currentValue) {
 95	            siftUp(index);
 96	            return;
 97	        }
 98	
 99	        if (newValue > currentValue) {
100	            siftDown(index);
101	        }
102	    }
103	
104	    void decreaseKey(int index, int newValue) {
105	        validateOccupiedIndex(index);
106	        ensureValueDecreases(index, newValue);
107	        updateValue(index, newValue);
108	    }
109	
110	    void increaseKey(int index, int newValue) {
111	        validateOccupiedIndex(index);
112	        ensureValueIncreases(index, newValue);
113	        updateValue(index, newValue);
114	    }
115	
116	    void clear() {
117	        Arrays.fill(elements, 0, size, 0);
118	        size = 0;
119	    }
120	
121	    boolean isEmpty() {
122	        return size == 0;
123	    }
124	
125	    boolean isAtCapacity() {
126	        return size == elements.length;
127	    }
128	
129	    int size() {
130	        return size;
131	    }
132	
133	    int capacity() {
134	        return elements.length;
135	    }
136	
137	    int valueAt(int index) {
138	        validateOccupiedIndex(index);
139	        return elements[index];
140	    }
141	
142	    int[] toArray() {
143	        return copyOf(elements, size);
144	    }
145	
146	    private void appendAll(int[] values) {
147	        int originalSize = size;
148	        ensureCapacity(originalSize + values.length);
149	        System.arraycopy(values, 0, elements, originalSize, values.length);
150	        size += values.length;
151	    }
152	
153	    private void rebuildHeap() {
154	        for (int index = parentIndex(size - 1); index >= 0; index--) {
155	            siftDown(index);
156	        }
157	    }
158	
159	    private void ensureCapacity(int requiredCapacity) {
160	        if (requiredCapacity <= elements.length) {
161	            return;
162	        }
163	
164	        int newCapacity = elements.length == 0 ? 1 : elements.length;
165	        while (newCapacity < requiredCapacity) {
166	            newCapacity *= 2;
167	        }
168	
169	        elements = Arrays.copyOf(elements, newCapacity);
170	    }
171	
172	    private void siftUp(int index) {
173	        while (index > 0) {
174	            int parentIndex = parentIndex(index);
175	            if (elements[parentIndex] <= elements[index]) {
176	                return;
177	            }
178	
179	            swap(index, parentIndex);
180	            index = parentIndex;
181	        }
182	    }
183	
184	    private void siftDown(int index) {
185	        while (true) {
186	            int leftChildIndex = leftChildIndex(index);
187	            int rightChildIndex = rightChildIndex(index);
188	            int smallestIndex = index;
189	
190	            if (leftChildIndex < size && elements[leftChildIndex] < elements[smallestIndex]) {
191	                smallestIndex = leftChildIndex;
192	            }
193	
194	            if (rightChildIndex < size && elements[rightChildIndex] < elements[smallestIndex]) {
195	                smallestIndex = rightChildIndex;
196	            }
197	
198	            if (smallestIndex == index) {
199	                return;
200	            }
201	
202	            swap(index, smallestIndex);
203	            index = smallestIndex;
204	        }
205	    }
206	
207	    private void restoreHeapAt(int index) {
208	        if (index > 0 && elements[index] < elements[parentIndex(index)]) {
209	            siftUp(index);
210	            return;
211	        }
212	
213	        siftDown(index);
214	    }
215	
216	    private void swap(int firstIndex, int secondIndex) {
217	        int temp = elements[firstIndex];
218	        elements[firstIndex] = elements[secondIndex];
219	        elements[secondIndex] = temp;
220	    }
221	
222	    private void ensureNotEmpty() {
223	        if (isEmpty()) {
224	            throw new NoSuchElementException("heap is empty");
225	        }
226	    }
227	
228	    private void validateOccupiedIndex(int index) {
229	        if (index < 0 || index >= size) {
230	            throw new IndexOutOfBoundsException(
231	                "index " + index + " is outside heap size " + size
232	            );
233	        }
234	    }
235	
236	    private void ensureValueDecreases(int index, int newValue) {
237	        if (newValue > elements[index]) {
238	            throw new IllegalArgumentException(
239	                "new value " + newValue + " is greater than current value " + elements[index]
240	            );
241	        }
242	    }
243	
244	    private void ensureValueIncreases(int index, int newValue) {
245	        if (newValue < elements[index]) {
246	            throw new IllegalArgumentException(
247	                "new value " + newValue + " is less than current value " + elements[index]
248	            );
249	        }
250	    }
251	
252	    private int parentIndex(int index) {
253	        return (index - 1) / 2;
254	    }
255	
256	    private int leftChildIndex(int index) {
257	        return index * 2 + 1;
258	    }
259	
260	    private int rightChildIndex(int index) {
261	        return index * 2 + 2;
262	    }
263	
264	    private static int[] copyOf(int[] values) {
265	        return copyOf(values, values.length);
266	    }
267	
268	    private static int[] copyOf(int[] values, int length) {
269	        return Arrays.copyOf(values, length);
270	    }
271	}

